    "schemaSnippet": "`FintechComplianceLedger (record_id VARCHAR(32) PRIMARY KEY, entity_name VARCHAR(64), status VARCHAR(20), amount_usd DECIMAL(10,2), risk_score INT, balance_usd DECIMAL(10,2), tax_identification_number VARCHAR(32), phone_confirmed BOOLEAN, country VARCHAR(3), audit_flag BOOLEAN, region_code VARCHAR(16), is_licensed BOOLEAN, parent_category_id INT, is_fraud_flagged BOOLEAN, is_chargeback BOOLEAN, discount_rate DECIMAL(4,2), gross_revenue DECIMAL(10,2), fulfillment_state VARCHAR(20), tier_level VARCHAR(10), tenure_months INT, annual_spend DECIMAL(12,2), is_blocked BOOLEAN)`",
