    "schemaSnippet": "`PlatformsDirectory (record_id VARCHAR(32) PRIMARY KEY, code_identifier VARCHAR(32), tracking_serial VARCHAR(64), entity_name VARCHAR(64), routing_code VARCHAR(32), account_number VARCHAR(32), tax_id VARCHAR(32), city_name VARCHAR(64), first_name VARCHAR(32), last_name VARCHAR(32), department VARCHAR(32), status_code VARCHAR(20), invoice_number VARCHAR(32), postal_code VARCHAR(16))`",
