    "schemaSnippet": "`PlatformsAuditQueue (record_id VARCHAR(32) PRIMARY KEY, entity_name VARCHAR(64), amount_usd DECIMAL(10,2), transaction_id BIGINT, created_at TIMESTAMP, created_date DATE, incident_id BIGINT, priority_level INT, annual_contract_value DECIMAL(12,2), city_name VARCHAR(64), stock_quantity INT, sku_id VARCHAR(32), student_name VARCHAR(64), student_id INT, p99_latency_ms INT, server_id VARCHAR(20), timestamp_epoch BIGINT, event_uuid VARCHAR(36))`",
